import { notFound } from "next/navigation";
import { respondToOpportunity } from "../actions";
import { requireUser } from "@/src/lib/auth/session";
import { isFirebaseOperationalBackend } from "@/src/lib/firebase/platform";
import { getFirebaseVendorOpportunity } from "@/src/lib/firebase/service-requests";
import { createSupabaseServerClient } from "@/src/lib/supabase/server";

export default async function OpportunityDetail({params}:{params:Promise<{id:string}>}){
  const user=await requireUser();const vendor=user.memberships.find(m=>m.organizationType==="vendor");if(!vendor)notFound();const {id}=await params;
  if(isFirebaseOperationalBackend()){
    const opportunity=await getFirebaseVendorOpportunity(user,id);if(!opportunity)notFound();const accepted=Boolean(opportunity.private);
    return <div><p className="text-sm font-semibold text-emerald-700">Vendor opportunity</p><h1 className="mt-1 text-4xl font-semibold">{opportunity.request.categoryName}</h1><p className="mt-3 text-sm text-slate-500">{opportunity.request.serviceAreaKey} · {opportunity.request.priority.replaceAll("_"," ")} · {opportunity.request.status}</p><section className="mt-8 grid gap-6 lg:grid-cols-[1fr_.7fr]"><div className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-bold">Request details</h2><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-slate-600">{opportunity.request.problemDescription}</p>{accepted?<div className="mt-6 rounded-xl bg-emerald-50 p-4 text-sm"><p className="font-bold">Authorized property details</p><p className="mt-2">{String(opportunity.private?.exactAddress)}<br/>{String(opportunity.private?.contactName)}<br/>{String(opportunity.private?.contactPhone??opportunity.private?.contactEmail??"")}</p></div>:<p className="mt-6 rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Exact property and contact details become available after you accept this opportunity.</p>}<h2 className="mt-7 font-bold">Request timeline</h2>{opportunity.events.map(event=><p key={event.id} className="mt-2 rounded-lg bg-slate-50 p-3 text-sm">{String(event.status)} · {String(event.note??"Update")}</p>)}</div><aside className="rounded-2xl border border-slate-200 bg-white p-6"><h2 className="font-bold">Respond</h2>{opportunity.assignment.status==="assigned"?<><form action={respondToOpportunity} className="mt-4"><input type="hidden" name="id" value={id}/><input type="hidden" name="action" value="accept"/><button className="min-h-11 w-full rounded-xl bg-emerald-700 text-sm font-bold text-white">Accept opportunity</button></form><form action={respondToOpportunity} className="mt-3"><input type="hidden" name="id" value={id}/><input type="hidden" name="action" value="decline"/><textarea name="reason" maxLength={500} className="min-h-20 w-full rounded-xl border p-3"/><button className="mt-2 min-h-11 w-full rounded-xl border border-rose-200 text-sm font-bold text-rose-700">Decline opportunity</button></form></>:null}{opportunity.request.status==="accepted"?<form action={respondToOpportunity} className="mt-4"><input type="hidden" name="id" value={id}/><input type="hidden" name="action" value="in_progress"/><button className="min-h-11 w-full rounded-xl bg-slate-950 text-sm font-bold text-white">Start work</button></form>:null}{opportunity.request.status==="in_progress"?<form action={respondToOpportunity} className="mt-4"><input type="hidden" name="id" value={id}/><input type="hidden" name="action" value="completed"/><button className="min-h-11 w-full rounded-xl bg-slate-950 text-sm font-bold text-white">Mark completed</button></form>:null}</aside></section></div>;
  }
  const db=await createSupabaseServerClient();const [{data:request},{data:history}]=await Promise.all([db.from("property_manager_service_requests").select("*,properties(name,address_line_1,cities(name,state_code)),vendor_categories(name)").eq("id",id).eq("assigned_vendor_organization_id",vendor.organizationId).maybeSingle(),db.from("property_manager_service_request_history").select("status,note,created_at,vendor_visible").eq("request_id",id).eq("vendor_visible",true).order("created_at")]);if(!request)notFound();const accepted=request.accepted_vendor_organization_id===vendor.organizationId;
  return <div><h1 className="text-4xl font-semibold">Opportunity</h1><p className="mt-4">{request.problem_description}</p>{accepted?<p>{request.address}</p>:<p>Exact property and contact details become available after you accept this opportunity.</p>}{history?.map((item,index)=><p key={index}>{item.status}</p>)}</div>;
}
